import { Service } from 'typedi';
import { PharmacySubscriptionRepository } from '@/modules/pharmacySubscriptions/repository';
import { PharmacyCustomerService } from '@/modules/pharmacyCustomers/services';
import {
  IPharmacySubscription,
  CreateSubscriptionRequest,
  SubscriptionItemInput,
  SubscriptionOrderLinkage,
  UpdateSubscriptionRequest,
  SubscriptionQueryParams,
} from '@/modules/pharmacySubscriptions/types';
import { AppError } from '@/modules/common/types';
import { parseDueRefillQuery, requireRefillPharmacyScope } from '../validation';

@Service()
export class PharmacySubscriptionService {
  constructor(
    private repo: PharmacySubscriptionRepository,
    private customerService: PharmacyCustomerService
  ) {}

  private async createManyAtomic(
    pharmacyId: string,
    userId: string,
    items: SubscriptionItemInput[],
    createdById: string,
    linkage?: SubscriptionOrderLinkage
  ): Promise<IPharmacySubscription[]> {
    const created: IPharmacySubscription[] = [];

    try {
      for (const item of items) {
        const subscription = await this.createOne(pharmacyId, userId, item, createdById, linkage);
        created.push(subscription);
      }
      return created;
    } catch (error) {
      for (let index = created.length - 1; index >= 0; index -= 1) {
        await this.repo.delete({ _id: created[index]._id }).catch(() => undefined);
      }
      throw error;
    }
  }

  async create(
    pharmacyId: string,
    data: CreateSubscriptionRequest,
    createdById: string
  ): Promise<IPharmacySubscription[]> {
    // Enforce privacy: user must be linked to this pharmacy
    await this.customerService.assertLinked(pharmacyId, data.userId);

    return this.createManyAtomic(pharmacyId, data.userId, data.items, createdById);
  }

  async createManyForUser(
    pharmacyId: string,
    userId: string,
    items: SubscriptionItemInput[],
    createdById: string,
    linkage?: SubscriptionOrderLinkage
  ): Promise<IPharmacySubscription[]> {
    if (!items.length) {
      return [];
    }

    await this.customerService.assertLinked(pharmacyId, userId);
    return this.createManyAtomic(pharmacyId, userId, items, createdById, linkage);
  }

  async createManyForOrder(
    pharmacyId: string,
    userId: string,
    items: SubscriptionItemInput[],
    createdById: string,
    linkage: SubscriptionOrderLinkage
  ): Promise<IPharmacySubscription[]> {
    return this.createManyForUser(pharmacyId, userId, items, createdById, linkage);
  }

  async reconcileForOrder(
    pharmacyId: string,
    userId: string,
    sourceOrderId: string,
    sourceOrderStatus: string,
    items: SubscriptionItemInput[],
    createdById: string
  ): Promise<void> {
    await this.customerService.assertLinked(pharmacyId, userId);

    const existingSubscriptions = await this.repo.findBySourceOrderId(sourceOrderId);
    const nextItemsByMedicine = new Map(items.map((item) => [item.medicineId, item]));
    const existingByMedicine = new Map(
      existingSubscriptions.map((subscription) => [String(subscription.medicineId), subscription])
    );

    for (const subscription of existingSubscriptions) {
      const medicineId = String(subscription.medicineId);
      const nextItem = nextItemsByMedicine.get(medicineId);

      if (!nextItem) {
        await this.repo.update(
          { _id: subscription._id },
          {
            isActive: false,
            sourceOrderStatus,
            lastSyncStatus: 'synced',
            lastSyncError: undefined,
          }
        );
        continue;
      }

      await this.repo.update(
        { _id: subscription._id },
        {
          userId,
          medicineName: nextItem.medicineName,
          frequency: nextItem.frequency,
          intervalDays: nextItem.intervalDays,
          nextRefillDate: nextItem.nextRefillDate,
          reminderChannel: nextItem.reminderChannel ?? 'push',
          isActive: true,
          sourceOrderStatus,
          lastSyncStatus: 'synced',
          lastSyncError: undefined,
          createdById,
          createdByRole: 'pharmacy',
        }
      );
    }

    const newItems = items.filter((item) => !existingByMedicine.has(item.medicineId));
    if (newItems.length) {
      await this.createManyForOrder(pharmacyId, userId, newItems, createdById, {
        sourceOrderId,
        sourceOrderStatus,
        lastSyncStatus: 'synced',
      });
    }
  }

  private createOne(
    pharmacyId: string,
    userId: string,
    item: SubscriptionItemInput,
    createdById: string,
    linkage?: SubscriptionOrderLinkage
  ): Promise<IPharmacySubscription> {
    return this.repo.save({
      pharmacyId,
      userId,
      medicineId: item.medicineId,
      medicineName: item.medicineName,
      frequency: item.frequency,
      intervalDays: item.intervalDays,
      nextRefillDate: item.nextRefillDate,
      reminderChannel: item.reminderChannel ?? 'push',
      isActive: true,
      sourceOrderId: linkage?.sourceOrderId,
      sourceOrderStatus: linkage?.sourceOrderStatus,
      lastSyncStatus: linkage?.lastSyncStatus ?? 'synced',
      lastSyncError: linkage?.lastSyncError,
      createdById,
      createdByRole: 'pharmacy',
    });
  }

  async getDueRefills(pharmacyId: unknown, rawQuery: unknown) {
    const scope = requireRefillPharmacyScope(pharmacyId);
    return this.repo.findDueRefills(scope, parseDueRefillQuery(scope, rawQuery));
  }

  async getAll(filter: SubscriptionQueryParams) {
    return this.repo.findWithPagination(filter, filter.page ?? 1, filter.limit ?? 20);
  }

  async update(
    id: string,
    pharmacyId: string,
    data: UpdateSubscriptionRequest
  ): Promise<IPharmacySubscription> {
    const sub = await this.repo.findById(id);
    if (!sub) {
      throw new AppError({ status: 404, code: 'SUBSCRIPTION_NOT_FOUND', message: 'Subscription not found' });
    }
    if (String(sub.pharmacyId) !== pharmacyId) {
      throw new AppError({ status: 403, code: 'FORBIDDEN', message: 'Access denied' });
    }

    const nextPayload: UpdateSubscriptionRequest = { ...data };
    if (data.isActive === true) {
      delete nextPayload.pausedUntil;
    }

    const updated = await this.repo.update({ _id: id }, data.isActive === true
      ? { $set: nextPayload, $unset: { pausedUntil: '' } }
      : nextPayload);
    if (!updated) {
      throw new AppError({ status: 500, code: 'UPDATE_FAILED', message: 'Failed to update subscription' });
    }
    return updated;
  }

  async pause(id: string, pharmacyId: string, pausedUntil?: string): Promise<IPharmacySubscription> {
    return this.update(id, pharmacyId, {
      isActive: false,
      pausedUntil,
    });
  }

  async syncOrderLinkage(
    sourceOrderId: string,
    sourceOrderStatus: string,
    syncStatus: 'pending' | 'synced' | 'failed' = 'synced',
    syncError?: string
  ): Promise<void> {
    await this.repo.updateMany(
      { sourceOrderId },
      {
        sourceOrderStatus,
        lastSyncStatus: syncStatus,
        lastSyncError: syncError,
      }
    );
  }

  async delete(id: string, pharmacyId: string): Promise<void> {
    const sub = await this.repo.findById(id);
    if (!sub) {
      throw new AppError({ status: 404, code: 'SUBSCRIPTION_NOT_FOUND', message: 'Subscription not found' });
    }
    if (String(sub.pharmacyId) !== pharmacyId) {
      throw new AppError({ status: 403, code: 'FORBIDDEN', message: 'Access denied' });
    }

    await this.repo.delete({ _id: id });
  }
}

export const REFILL_REMINDER_CHANNELS = Object.freeze(['sms', 'push', 'both', 'none'] as const);
export type ReminderChannel = typeof REFILL_REMINDER_CHANNELS[number];
export type SubscriptionSyncStatus = 'pending' | 'synced' | 'failed';

export interface IPharmacySubscription {
  _id?: string;
  pharmacyId: string;
  userId: string;
  medicineId: string;
  medicineName?: string;
  frequency?: string;
  intervalDays: number;
  nextRefillDate?: string;
  reminderChannel?: ReminderChannel;
  isActive?: boolean;
  pausedUntil?: string;
  sourceOrderId?: string;
  sourceOrderStatus?: string;
  lastSyncStatus?: SubscriptionSyncStatus;
  lastSyncError?: string;
  createdById?: string;
  createdByRole?: string;
  createdAt?: Date;
  updatedAt?: Date;
}

export interface SubscriptionItemInput {
  medicineId: string;
  medicineName?: string;
  frequency?: string;
  intervalDays: number;
  nextRefillDate?: string;
  reminderChannel?: ReminderChannel;
}

export interface CreateSubscriptionRequest {
  userId: string;
  items: SubscriptionItemInput[];
}

export interface SubscriptionOrderLinkage {
  sourceOrderId: string;
  sourceOrderStatus: string;
  lastSyncStatus?: SubscriptionSyncStatus;
  lastSyncError?: string;
}

export interface UpdateSubscriptionRequest {
  intervalDays?: number;
  nextRefillDate?: string;
  reminderChannel?: ReminderChannel;
  isActive?: boolean;
  pausedUntil?: string;
}

export interface SubscriptionQueryParams {
  pharmacyId?: string;
  userId?: string;
  medicineId?: string;
  isActive?: boolean;
  page?: number;
  limit?: number;
}

/** Internal parsed primitives; only parseDueRefillQuery constructs this read input. */
export interface DueRefillCursor {
  readonly v: 1;
  readonly pharmacyId: string;
  readonly through: string;
  readonly limit: number;
  readonly nextRefillDate: string;
  readonly subscriptionId: string;
}
export interface DueRefillQuery {
  readonly through: string;
  readonly limit: number;
  readonly after?: DueRefillCursor;
}
export interface DueRefillRow {
  subscriptionId: string;
  nextRefillDate: string;
  intervalDays: number;
  reminderChannel: ReminderChannel | null;
  pausedUntil: string | null;
  pauseEvaluation: 'not_evaluated';
}
export interface DueRefillPage {
  through: string;
  limit: number;
  items: DueRefillRow[];
  nextCursor: string | null;
}

import Joi from 'joi';
import { types } from 'util';
import { AppError } from '@/modules/common/types';
import { DueRefillCursor, DueRefillQuery, DueRefillRow } from '../types';

const subscriptionItemSchema = Joi.object({
  medicineId: Joi.string().pattern(/^[0-9a-fA-F]{24}$/).required(),
  medicineName: Joi.string().trim().optional(),
  frequency: Joi.string().trim().optional(),
  intervalDays: Joi.number().integer().min(1).required(),
  nextRefillDate: Joi.string().pattern(/^\d{8}$/).optional(),
  reminderChannel: Joi.string().valid('sms', 'push', 'both', 'none').optional(),
});

export const createSubscriptionSchema = Joi.object({
  userId: Joi.string().pattern(/^[0-9a-fA-F]{24}$/).required(),
  items: Joi.array().items(subscriptionItemSchema).min(1).required(),
});

export const updateSubscriptionSchema = Joi.object({
  intervalDays: Joi.number().integer().min(1).optional(),
  nextRefillDate: Joi.string().pattern(/^\d{8}$/).optional(),
  reminderChannel: Joi.string().valid('sms', 'push', 'both', 'none').optional(),
  isActive: Joi.boolean().optional(),
}).min(1);

export const pauseSubscriptionSchema = Joi.object({
  pausedUntil: Joi.string().pattern(/^\d{8}$/).optional(),
});

export const idParamSchema = Joi.object({
  id: Joi.string().pattern(/^[0-9a-fA-F]{24}$/).required(),
});

const refillQueryError = () => new AppError({ status: 400, code: 'VALIDATION_ERROR', message: 'Invalid refill worklist query' });

/** A calendar label, with no host-timezone/current-date interpretation. */
export function isRefillCalendarDate(value: unknown): value is string {
  if (typeof value !== 'string' || !/^[0-9]{8}$/.test(value)) return false;
  const year = Number(value.slice(0, 4)), month = Number(value.slice(4, 6)), day = Number(value.slice(6, 8));
  if (year === 0 || month < 1 || month > 12 || day < 1 || day > 31) return false;
  const date = new Date(0);
  date.setUTCFullYear(year, month - 1, day);
  return date.getUTCFullYear() === year && date.getUTCMonth() === month - 1 && date.getUTCDate() === day;
}

export function requireRefillPharmacyScope(value: unknown): string {
  if (typeof value !== 'string' || !/^[0-9a-f]{24}$/.test(value)) {
    throw new AppError({ status: 403, code: 'FORBIDDEN', message: 'Access denied' });
  }
  return value;
}

function refillData(value: unknown, keys: readonly string[]): Record<string, unknown> {
  if (!value || typeof value !== 'object' || Array.isArray(value) || types.isProxy(value) ||
    ![Object.prototype, null].includes(Object.getPrototypeOf(value))) throw refillQueryError();
  const out: Record<string, unknown> = {};
  for (const key of Reflect.ownKeys(value)) {
    if (typeof key !== 'string' || !keys.includes(key)) throw refillQueryError();
    const descriptor = Object.getOwnPropertyDescriptor(value, key);
    if (!descriptor || !('value' in descriptor) || !descriptor.enumerable) throw refillQueryError();
    out[key] = descriptor.value;
  }
  return out;
}

function refillCursorText(cursor: DueRefillCursor): string {
  return Buffer.from(JSON.stringify({ v: cursor.v, pharmacyId: cursor.pharmacyId, through: cursor.through,
    limit: cursor.limit, nextRefillDate: cursor.nextRefillDate, subscriptionId: cursor.subscriptionId }), 'utf8').toString('base64url');
}

export function parseDueRefillQuery(pharmacyId: string, raw: unknown): DueRefillQuery {
  requireRefillPharmacyScope(pharmacyId);
  const query = refillData(raw, ['through', 'limit', 'after']);
  if (!isRefillCalendarDate(query.through) || (query.limit !== undefined &&
    (typeof query.limit !== 'string' || !/^(?:[1-9]|[1-4][0-9]|50)$/.test(query.limit)))) throw refillQueryError();
  const through = query.through, limit = query.limit === undefined ? 20 : Number(query.limit);
  let after: DueRefillCursor | undefined;
  if (query.after !== undefined) {
    if (typeof query.after !== 'string' || !/^[A-Za-z0-9_-]{1,384}$/.test(query.after)) throw refillQueryError();
    const bytes = Buffer.from(query.after, 'base64url');
    if (bytes.length > 288 || bytes.toString('base64url') !== query.after || !Buffer.from(bytes.toString('utf8'), 'utf8').equals(bytes)) throw refillQueryError();
    let decoded: unknown;
    try { decoded = JSON.parse(bytes.toString('utf8')); } catch { throw refillQueryError(); }
    const cursor = refillData(decoded, ['v', 'pharmacyId', 'through', 'limit', 'nextRefillDate', 'subscriptionId']);
    if (Object.keys(cursor).length !== 6 || cursor.v !== 1 || cursor.pharmacyId !== pharmacyId || cursor.through !== through ||
      cursor.limit !== limit || !isRefillCalendarDate(cursor.nextRefillDate) || cursor.nextRefillDate > through ||
      typeof cursor.subscriptionId !== 'string' || !/^[0-9a-f]{24}$/.test(cursor.subscriptionId)) throw refillQueryError();
    after = Object.freeze({ v: 1, pharmacyId, through, limit, nextRefillDate: cursor.nextRefillDate, subscriptionId: cursor.subscriptionId });
    // Fixed-order serialization also rejects duplicate keys and alternate JSON spelling/order.
    if (refillCursorText(after) !== query.after) throw refillQueryError();
  }
  return Object.freeze({ through, limit, ...(after ? { after } : {}) });
}

export function encodeDueRefillCursor(pharmacyId: string, query: DueRefillQuery, row: DueRefillRow): string {
  return refillCursorText({ v: 1, pharmacyId, through: query.through, limit: query.limit,
    nextRefillDate: row.nextRefillDate, subscriptionId: row.subscriptionId });
}

