## Notes

- All date fields use `YYYYMMDD` format (e.g., `20260209`)
- Phone numbers must be exactly 10 digits
- The current [login source](src1/modules/auth/services/index.ts) generates random six-digit OTPs; there is no fixed testing code. Verification binds the code to the selected account and its current phone/email destination. The [OTP service](src1/modules/otp/services/index.ts) checks stored expiry and the [OTP repository](src1/modules/otp/repository/index.ts) conditionally consumes an unverified challenge through a single [database update](src1/modules/common/repository/BaseRepository.ts).
- MongoDB ObjectId format: 24 hexadecimal characters
- All endpoints except `/health` and `/api/v1/auth/*/send` and `/api/v1/auth/*/verify` require Bearer token authentication
- Token is automatically saved from the "Verify OTP" response and used in subsequent requests

import 'reflect-metadata';
import { Response, NextFunction } from 'express';
import { Container } from 'typedi';
import { PharmacySubscriptionService } from '@/modules/pharmacySubscriptions/services';
import { AuthRequest } from '@/modules/middleware/auth';

export class PharmacySubscriptionController {
  private service: PharmacySubscriptionService;

  constructor() {
    this.service = Container.get(PharmacySubscriptionService);
  }

  create = async (req: AuthRequest, res: Response, _next: NextFunction) => {
    const pharmacyId = req.user?.pharmacyId || '';
    const result = await this.service.create(pharmacyId, req.body, req.user?._id || '');
    res.status(201).json({ success: true, message: 'Subscriptions created', data: result });
  };

  list = async (req: AuthRequest, res: Response, _next: NextFunction) => {
    const q = req.query as Record<string, string | undefined>;
    const pharmacyId = req.user?.pharmacyId || q.pharmacyId || '';
    const result = await this.service.getAll({
      pharmacyId,
      userId: q.userId,
      medicineId: q.medicineId,
      isActive: q.isActive !== undefined ? q.isActive === 'true' : undefined,
      page: q.page ? parseInt(q.page) : 1,
      limit: q.limit ? parseInt(q.limit) : 20,
    });
    res.status(200).json({
      success: true,
      data: result.data,
      pagination: { page: result.page, limit: 20, total: result.total, totalPages: result.totalPages },
    });
  };

  update = async (req: AuthRequest, res: Response, _next: NextFunction) => {
    const pharmacyId = req.user?.pharmacyId || '';
    const result = await this.service.update(req.params.id, pharmacyId, req.body);
    res.status(200).json({ success: true, message: 'Subscription updated', data: result });
  };

  pause = async (req: AuthRequest, res: Response, _next: NextFunction) => {
    const pharmacyId = req.user?.pharmacyId || '';
    const result = await this.service.pause(req.params.id, pharmacyId, req.body.pausedUntil);
    res.status(200).json({ success: true, message: 'Subscription paused', data: result });
  };

  delete = async (req: AuthRequest, res: Response, _next: NextFunction) => {
    const pharmacyId = req.user?.pharmacyId || '';
    await this.service.delete(req.params.id, pharmacyId);
    res.status(200).json({ success: true, message: 'Subscription deleted' });
  };
}

import { Service } from 'typedi';
import { Model } from 'mongoose';
import PharmacySubscriptionModel from '@/modules/pharmacySubscriptions/model';
import { IPharmacySubscription, SubscriptionQueryParams } from '@/modules/pharmacySubscriptions/types';
import { BaseRepository } from '@/modules/common/repository';

@Service()
export class PharmacySubscriptionRepository extends BaseRepository<IPharmacySubscription> {
  constructor() {
    super(PharmacySubscriptionModel as Model<IPharmacySubscription>);
  }

  async findWithPagination(
    filter: SubscriptionQueryParams,
    page = 1,
    limit = 20
  ): Promise<{ data: IPharmacySubscription[]; total: number; page: number; totalPages: number }> {
    const query: any = {};
    if (filter.pharmacyId) query.pharmacyId = filter.pharmacyId;
    if (filter.userId) query.userId = filter.userId;
    if (filter.medicineId) query.medicineId = filter.medicineId;
    if (filter.isActive !== undefined) query.isActive = filter.isActive;

    const skip = (page - 1) * limit;
    const [data, total] = await Promise.all([
      PharmacySubscriptionModel.find(query)
        .populate('medicineId', 'name genericName')
        .populate('userId', 'name phone')
        .sort({ nextRefillDate: 1 })
        .skip(skip)
        .limit(limit)
        .lean(),
      PharmacySubscriptionModel.countDocuments(query),
    ]);

    return { data, total, page, totalPages: Math.ceil(total / limit) };
  }

  async findBySourceOrderId(sourceOrderId: string): Promise<IPharmacySubscription[]> {
    return PharmacySubscriptionModel.find({ sourceOrderId }).lean();
  }
}

